<?php $title='Atualizações'; ?><section class="page-head"><div><h1>Atualizações</h1><p>Atualize a GDA Plataforma com pacotes assinados pelo formato esperado.</p></div></section>
<div class="stats"><article class="stat"><span>Versão atual</span><strong><?= e($version['version']) ?></strong></article><article class="stat"><span>Data da versão</span><strong><?= e(date('d/m/Y',strtotime($version['release_date']))) ?></strong></article><article class="stat"><span>Último backup</span><strong><?= e($lastBackup) ?></strong></article></div>
<section class="panel update-box"><h2>Analisar novo pacote</h2><p>O pacote não será instalado antes da análise e da confirmação da sua senha.</p><form method="post" action="<?= e(base_url('atualizacoes/analisar')) ?>" enctype="multipart/form-data" data-loading><?= csrf_field() ?><label>Pacote ZIP *<input type="file" name="package" accept=".zip,application/zip" required></label><label class="check"><input type="checkbox" name="backup" value="1" checked> Criar backup antes da atualização</label><button class="btn primary">Analisar pacote</button></form></section>
<section class="panel"><div class="panel-head"><h2>Histórico de atualizações</h2></div><?php if(!$history): ?><div class="empty">Nenhuma atualização realizada.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Versão</th><th>Arquivo</th><th>Responsável</th><th>Status</th><th>Resumo</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($h['created_at']))) ?></td><td><?= e($h['previous_version']) ?> → <?= e($h['new_version']) ?></td><td><?= e($h['filename']) ?><small><?= e(number_format($h['file_size']/1024,1,',','.')) ?> KB</small></td><td><?= e($h['user_name']??'Sistema') ?></td><td><span class="badge"><?= e($h['status']) ?></span></td><td><?= e($h['summary']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>

